function validate([cookies, k]) {
  if (!Array.isArray(cookies) || cookies.length < 2 || cookies.length > 8) return 'cookies needs 2 to 8 bags.';
  if (cookies.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each bag holds between 1 and 100000 cookies.';
  if (!Number.isInteger(k) || k < 2 || k > cookies.length) return 'k is between 2 and the number of bags.';
  return null;
}

