function distributeCookies(cookies, k) {
  const bags = [...cookies].sort((a, b) => b - a);
  const loads = new Array(k).fill(0);
  let best = Infinity;

  function place(index, worst) {
    if (worst >= best) {
      return;
    }
    if (index === bags.length) {
      best = worst;
      return;
    }
    for (let child = 0; child < k; child++) {
      loads[child] += bags[index];
      place(index + 1, Math.max(worst, loads[child]));
      loads[child] -= bags[index];
      if (loads[child] === 0) {
        break;
      }
    }
  }

  place(0, 0);
  return best;
}

