function distributeCookies(cookies, k) {
  const n = cookies.length, full = (1 << n) - 1;
  const total = new Array(1 << n).fill(0);
  for (let mask = 1; mask <= full; mask++) {
    const low = mask & -mask;
    total[mask] = total[mask ^ low] + cookies[31 - Math.clz32(low)];
  }
  // cost[mask] = best unfairness when the bags in mask go to the children handled so far.
  let cost = total.slice();
  for (let child = 2; child <= k; child++) {
    const next = new Array(1 << n).fill(Infinity);
    for (let mask = 0; mask <= full; mask++) {
      for (let sub = mask; ; sub = (sub - 1) & mask) {
        next[mask] = Math.min(next[mask], Math.max(cost[mask ^ sub], total[sub]));
        if (sub === 0) break;
      }
    }
    cost = next;
  }
  return cost[full];
}

