function generate(rand, size) {
  const n = size === 'large' ? 7 + Math.floor(rand() * 2) : 2 + Math.floor(rand() * 5);
  const k = 2 + Math.floor(rand() * (n - 1));
  const top = size === 'large' ? 100000 : (rand() < 0.5 ? 10 : 100000);
  const cookies = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  return [cookies, k];
}
